            _corner_index(indices[1], f"{label} UV index", optional=True)
            _corner_index(indices[2], f"{label} normal index", optional=True)


def _operation(entry: Mapping[str, object], node_id: str) -> Operation:
    """Return the operation selected by an operation or generator node."""
    operation = _named_enum(entry, "operation", Operation, "operation", node_id)
    assert isinstance(operation, Operation)
    return operation


def _validate_node(entry: Mapping[str, object], node_id: str) -> None:
    """Validate every field read while rebuilding one graphics node."""
    if "name" in entry and (
        not isinstance(entry["name"], str) or not entry["name"].strip()
    ):
        raise GraphError(f"Node {node_id!r} name must be non-empty text")
    _number(_required(entry, "x", node_id), f"Node {node_id!r} x")
    _number(_required(entry, "y", node_id), f"Node {node_id!r} y")
    kind = entry["kind"]

    if kind == "value":
        math_type = _named_enum(entry, "math_type", MathType, "math type", node_id)
        assert isinstance(math_type, MathType)
        _components(
            _required(entry, "components", node_id),
            math_type,
            f"Node {node_id!r} components",
        )
    elif kind == "operation":
        operation = _operation(entry, node_id)
        if operation in GENERATOR_OPERATIONS:
            raise GraphError(f"{operation.value} must be a generator node")
    elif kind == "generator":
        operation = _operation(entry, node_id)
        if operation not in GENERATOR_OPERATIONS:
            raise GraphError(f"{operation.value} must be an operation node")
        parameters = _sequence(
            _required(entry, "parameters", node_id),
            f"Node {node_id!r} parameters",
        )
        parameter_types = OPERATION_PARAMETER_TYPES[operation]
        if len(parameters) != len(parameter_types):
            raise GraphError(
                f"{operation.value} needs {len(parameter_types)} parameters"
            )
        for index, (parameter, math_type) in enumerate(
            zip(parameters, parameter_types, strict=True)
        ):
            _components(parameter, math_type, f"Parameter {index}")
    elif kind == "obj_loader":
        array_ids = _sequence(
            _required(entry, "array_ids", node_id), "Obj Loader array ids"
        )
        if len(array_ids) != 4:
            raise GraphError("Obj Loader needs four array ids")
        if any(not isinstance(array_id, str) or not array_id for array_id in array_ids):
            raise GraphError("Obj Loader array ids must be non-empty strings")
        if len(set(array_ids)) != len(array_ids):
            raise GraphError("Obj Loader array ids must be unique")
        if array_ids[0] != node_id:
            raise GraphError("Obj Loader id must match its Vertices array id")
        _vectors(_required(entry, "vertices", node_id), 3, "Obj Loader vertices")
        _faces(_required(entry, "faces", node_id))
        _vectors(_required(entry, "uvs", node_id), 2, "Obj Loader UVs")
        _vectors(_required(entry, "normals", node_id), 3, "Obj Loader normals")
        status = entry.get("status", "")
        if not isinstance(status, str):
            raise GraphError("Obj Loader status must be text")
    elif kind == "mesh_viewer":
        shading_mode = entry.get("shading_mode", "Solid Colour")
        if shading_mode not in SHADING_MODES:
            raise GraphError(f"Unknown shading mode {shading_mode!r}")
        if "wireframe" in entry and not isinstance(entry["wireframe"], bool):
            raise GraphError("Mesh Viewer wireframe must be true or false")


def _input_count(entry: Mapping[str, object]) -> int:
    """Return the number of sockets which accept connections on a node."""
    kind = entry["kind"]
    if kind == "output":
        return 1
    if kind == "mesh_viewer":
        return len(MESH_VIEWER_INPUT_NAMES)
    if kind == "operation":
        return OPERATION_ARITY[_operation(entry, str(entry["id"]))]
    return 0


def validate_document(data: object) -> None:
    """Check a document completely before it replaces the current scene."""
    if not isinstance(data, Mapping):
        raise GraphError("Document must be an object")
    version = data.get("schema_version")
    if "schema_version" in data and (
        not isinstance(version, int)
        or isinstance(version, bool)
        or version != SCHEMA_VERSION
    ):
        raise GraphError(f"Unsupported graph schema version {version!r}")
    for field in ("nodes", "connections"):
        if field not in data:
            raise GraphError(f"Document is missing {field!r}")

    nodes = _sequence(data["nodes"], "Document nodes")
    node_ids: set[str] = set()
    node_entries: dict[str, Mapping[str, object]] = {}
    for entry in nodes:
        if not isinstance(entry, Mapping):
            raise GraphError("Each document node must be an object")
        node_id = entry.get("id")
        if not isinstance(node_id, str) or not node_id:
            raise GraphError("Node id must be a non-empty string")
        if node_id in node_ids:
            raise GraphError(f"Duplicate node id {node_id!r}")
        kind = entry.get("kind")
        if kind not in NODE_KINDS:
            raise GraphError(f"Unknown node kind {kind!r}")
        node_ids.add(node_id)
        node_entries[node_id] = entry
        _validate_node(entry, node_id)

    source_ids: set[str] = set()
    source_owners: dict[str, str] = {}
    owned_array_ids: set[str] = set()
    for node_id, entry in node_entries.items():
        kind = entry["kind"]
        if kind in {"value", "operation", "generator"}:
            source_ids.add(node_id)
            source_owners[node_id] = node_id
        elif kind == "obj_loader":
            for index, array_id in enumerate(entry["array_ids"]):
                if array_id in owned_array_ids:
                    raise GraphError(f"Duplicate Obj Loader array id {array_id!r}")
                if index > 0 and array_id in node_ids:
                    raise GraphError(
                        f"Obj Loader array id {array_id!r} is already in use"
                    )
                owned_array_ids.add(array_id)
                source_ids.add(array_id)
                source_owners[array_id] = node_id

    connections = _sequence(data["connections"], "Document connections")
    occupied_inputs: set[tuple[str, int]] = set()
    for connection in connections:
        if not isinstance(connection, Mapping):
            raise GraphError("Each document connection must be an object")
        source_id = connection.get("source")
        if not isinstance(source_id, str) or not source_id:
            raise GraphError("Connection source must be a node id")
        if source_id not in source_ids:
            if source_id in node_ids:
                raise GraphError(f"Node {source_id!r} cannot be a connection source")
            raise GraphError(f"Unknown connection source {source_id!r}")
        target_id = connection.get("target")
        if not isinstance(target_id, str) or not target_id:
            raise GraphError("Connection target must be a node id")
        if target_id not in node_ids:
            raise GraphError(f"Unknown connection target {target_id!r}")
        if source_owners[source_id] == target_id:
            raise GraphError("A node cannot connect directly to itself")
        input_index = connection.get("input")
        input_count = _input_count(node_entries[target_id])
        if (
            not isinstance(input_index, int)
            or isinstance(input_index, bool)
            or not 0 <= input_index < input_count
        ):
            raise GraphError(
                f"Connection to {target_id!r} has invalid input {input_index!r}"
            )
        target_input = (target_id, input_index)
        if target_input in occupied_inputs:
            raise GraphError(
                f"Node {target_id!r} input {input_index} has multiple connections"
            )
        occupied_inputs.add(target_input)
# MathNodeEditor

![MathNodeEditor](MathNodeEditor.png)

This is a small PySide6 node editor for experimenting with the PyNGL maths classes. It reopens whichever graph you had open last; the first time you run it (or if that file's gone missing) it opens `examples/vec3_multiply_demo.json` instead — two editable `Vec3` nodes wired through a component multiply node, so changing any value updates the output straight away.

The value palette has `Float`, `Vec2`, `Vec3`, `Vec4`, `Mat2`, `Mat3`, `Mat4` and `Quaternion`. Quaternions use the same `(s, x, y, z)` order as PyNGL and start as the identity quaternion.

The Mat4 nodes cover translate, scale, rotation about each axis, `look_at`, perspective, orthographic and frustum projection, plus a `Transform` node wrapping PyNGL's `Transform` class (`Position`/`Rotation`/`Scale`, rotation in degrees, xyz order). These, and the quaternion axis-angle node, take their parameters from spin boxes built into the node itself rather than wired-in Value nodes — there's nothing to connect, just numbers to type. The remaining quaternion nodes (Hamilton product, vector rotation, conversion to and from `Mat4`, slerp, conjugate, inverse) still take wired inputs, since they combine other quaternions or matrices rather than raw numbers. The original add, subtract, component multiply, matrix multiply, dot, cross, normalise and transpose nodes are unchanged.

`Multiply` is explicitly component-wise (PyNGL reserves `*` for scalar multiplication), whilst `Matrix Multiply` and `Quaternion Product` use the normal `@` operation.

The Mesh group adds an `Obj Loader` node, which loads a triangulated `.obj` file and splits it into four separate outputs: `Vertices`, `Faces`, `UVs` and `Normals`. Non-triangular meshes are rejected with a graph error rather than auto-triangulated, same as `ColourObj`/`Obj2Numpy` elsewhere in this repo. `Transform Vertices` and `Transform Normals` let you push a matrix through those arrays — vertices take a `Mat4` (translation included), normals take a `Mat3` (translation dropped) — but the normal matrix isn't built for you. Wire up `Mat4 to Mat3` → `Inverse` → `Transpose` yourself if you want it correct under non-uniform scale, which is rather the point of a teaching tool.

A `Mesh Viewer` node merges `Vertices`/`Faces`/`UVs`/`Normals` (plus an optional `Colour` `Vec4`) back into a mesh and renders it live, using PyNGL's built-in shaders — pick `Solid Colour` or `Diffuse` from the dropdown and tick `Wireframe` for a line-only view. Bad face indices are reported on the node before they reach OpenGL, and Diffuse shading needs a non-empty normal array. It renders in two places at once: a small preview embedded in the node itself, and a pop-out window with the usual arcball camera (drag to rotate, right-drag to pan, wheel to zoom) via the `Pop Out` button.

Click a palette button to add a node, or move the pointer over the canvas and press `Tab` to open the node menu at that position. Start typing to filter the menu and press `Return` to create the first matching node. You can also select an entry with the mouse.

Drag from an output socket to an input socket to connect it. Double-click a node header to give it a useful name; the name is saved with the graph. Value nodes use zero vectors and identity matrices as their defaults. Generator nodes start pre-filled with sensible non-zero numbers instead, so a new Look At or Perspective node gives you something reasonable to look at straight away rather than a degenerate matrix. Numeric fields keep seven decimal places and the saved graph keeps the model's full value, so loading and saving doesn't quietly round a number to what happened to fit in the widget. The palette scrolls, the mouse wheel zooms the canvas (clamped to sensible limits) and nodes can be selected and dragged around — hover over a numeric field first and the wheel edits that value instead. Loaded graphs are framed automatically; press `H` to frame every node again after editing the layout.

Select a node or wire and press `Delete`/`Backspace` to remove it, or right-click it for the same option. The `File` menu's `New` (`Ctrl+N`), `Open...` (`Ctrl+O`), `Save` (`Ctrl+S`) and `Save As...` (`Ctrl+Shift+S`) read and write the graph as JSON — `Save` writes straight back to whichever file is open, prompting for one the first time. Version 1 files are checked completely before the current canvas is replaced, and saves use a temporary file so a failed write can't truncate the previous graph. Older files without a version number still load. `New`, `Open...` and closing the window all ask to save first if the graph has unsaved changes. The window remembers its size and the last file you had open between runs.

## Examples

There are fourteen saved graphs covering basic vector arithmetic, `Vec2 @ Mat2`, homogeneous coordinates, triangle normals, Lambert diffuse, transform order, normal matrices, camera projections, quaternions and mesh transforms. The [examples catalogue](examples/README.md) explains what each graph demonstrates and suggests a value to change.

Open any of them with `File` → `Open...`. `examples/vec3_multiply_demo.json` remains the starting graph when there is no previously opened file.

## Running it

```bash
uv run MathNodeEditor/main.py
uv run pytest MathNodeEditor/tests
```





